-- ============================================
-- 英语词汇表 最终版
-- 总词数: 14183
-- ============================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `vocabulary`;
CREATE TABLE `vocabulary` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `word` VARCHAR(255) NOT NULL,
  `phonetic` VARCHAR(500) DEFAULT NULL,
  `definition` TEXT DEFAULT NULL,
  `translation` TEXT DEFAULT NULL,
  `brief_translation` VARCHAR(100) DEFAULT NULL,
  `collins` VARCHAR(10) DEFAULT NULL,
  `oxford` VARCHAR(10) DEFAULT NULL,
  `tag` VARCHAR(200) DEFAULT NULL,
  `bnc` VARCHAR(20) DEFAULT NULL,
  `frq` VARCHAR(20) DEFAULT NULL,
  `exchange` VARCHAR(500) DEFAULT NULL,
  `uk_audio` VARCHAR(500) DEFAULT NULL,
  `us_audio` VARCHAR(500) DEFAULT NULL,
  `chinese_options` JSON DEFAULT NULL,
  `english_options` JSON DEFAULT NULL,
  PRIMARY KEY (`id`),
  INDEX `idx_word` (`word`),
  INDEX `idx_tag` (`tag`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


SET FOREIGN_KEY_CHECKS = 1;
